def choose_move(observation):
    wx, wy = observation['grid_width'], observation['grid_height']
    px, py = observation['self_position']
    ox, oy = observation['opponent_position']
    resources = observation['resources']
    obstacles = set(observation.get('obstacles', []))
    # Basic heuristics: move towards resource if available
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    # Find closest resource
    target = None
    min_dist = float('inf')
    for res in resources:
        d = dist((px, py), res)
        if d < min_dist:
            min_dist = d
            target = res
    # Simple move: towards resource if exists
    dx, dy = 0, 0
    if target:
        dx = (target[0] - px)
        dy = (target[1] - py)
        if dx != 0: dx = dx // abs(dx)
        if dy != 0: dy = dy // abs(dy)
    else:
        # No resource, move towards opponent to challenge, or stay
        dx = (ox - px)
        dy = (oy - py)
        if dx != 0: dx = dx // abs(dx)
        if dy != 0: dy = dy // abs(dy)
    new_x = px + dx
    new_y = py + dy
    # Avoid obstacles and boundaries
    if not (0 <= new_x < wx and 0 <= new_y < wy) or (new_x, new_y) in obstacles:
        # Try to move in alternative directions
        for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
            nx, ny = px+ddx, py+ddy
            if 0 <= nx < wx and 0 <= ny < wy and (nx, ny) not in obstacles:
                return [ddx, ddy]
        return [0,0]
    return [dx, dy]
